\title{Limit Points of Largest Matching Roots Below the Golden-Ratio Threshold}
\author{Aristotle}
\date{July 13, 2026}

\begin{document}

\begin{abstract}
Let $\tau = \tfrac12(1+\sqrt5)$ denote the golden ratio and set the threshold
$T = \sqrt{\tau} + 1/\sqrt{\tau} = \sqrt{2+\sqrt5} \approx 2.058$.
For a finite simple graph $G$, its matching polynomial has only real roots, and the largest matching root $\mu(G)$ is a natural spectral invariant. A conjectural picture --- parallel to the Smith/Hoffman--Shearer theory of adjacency-eigenvalue limit points --- asserts that the limit points of $\mu(G)$ below $T$ form a countable set of algebraic numbers manufactured by recursive constructions on the Dynkin families $A_n$ and $D_n$, with gaps at the transcendental values in between. We isolate and rigorously establish the cleanest concrete instance: the path family. We define the path matching polynomials by the edge-deletion recurrence, prove the Chebyshev-type evaluation $\mu(P_n)(2\cos\theta)\sin\theta = \sin((n+1)\theta)$, and deduce that the roots of $\mu(P_n)$ are exactly $\{2\cos(k\pi/(n+1)) : 1 \le k \le n\}$, so the largest matching root of $P_n$ is $2\cos(\pi/(n+1))$. These largest roots form a strictly increasing sequence in $(-T,T)$ converging to $2$; since $2 < T$, the number $2$ is a genuine accumulation point of largest matching roots strictly below the golden threshold. As a corollary, the largest matching root of $P_5$ equals the golden ratio exactly.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Matchings and the matching polynomial}
Let $G$ be a finite simple graph on $n$ vertices. A \emph{$k$-matching} is a set of $k$ pairwise vertex-disjoint edges; write $m(G,k)$ for their number, with $m(G,0)=1$. The \emph{matching polynomial} is
\[
\mu(G)(x) = \sum_{k\ge 0} (-1)^k\, m(G,k)\, x^{\,n-2k},
\]
a monic polynomial of degree $n$. By the Heilmann--Lieb theorem all its roots are real and bounded by $2\sqrt{\Delta-1}$ (with $\Delta$ the maximum degree), so the \emph{largest matching root}
\[
\mu(G) := \max\{x\in\R : \mu(G)(x)=0\}
\]
is well defined. For forests the matching polynomial equals the adjacency characteristic polynomial, so matching roots are adjacency eigenvalues; the study of their limit points continues the classical program of Smith, Hoffman, and Shearer.

\subsection{The golden threshold}
Set
\[
T = \sqrt{\tau} + \frac{1}{\sqrt{\tau}} = \sqrt{2+\sqrt5}, \qquad \tau = \frac{1+\sqrt5}{2}.
\]

\begin{conjecture}[limit points below $T$]
There is a countable set $S \subseteq [-T,T]$ equal to the set of limit points of largest matching roots $\mu(G)$ over all finite graphs that are less than $T$ in absolute value. Its elements are algebraic numbers arising as accumulation points of spectra of infinite families built by recursive operations on the Dynkin diagrams $A_n$ and $D_n$; the complement $(-T,T)\setminus S$ consists of transcendental gap values.
\end{conjecture}

\subsection{Contribution}
We give complete, self-contained proofs for the path family $\{A_n\}=\{P_n\}$: monicity and degree, the value at $2$, the Chebyshev evaluation, the exact root set, strict monotonicity and convergence of the largest roots to $2$, the threshold arithmetic $2 < T$, and the capstone that $2$ is an accumulation point of largest matching roots strictly below $T$. As a corollary the largest matching root of $P_5$ is exactly $\tau$.

\section{The path matching polynomial}

\begin{definition}
The \emph{path matching polynomials} $\mu(P_n)\in\R[x]$ are defined by
\[
\mu(P_0)=1,\qquad \mu(P_1)=x,\qquad \mu(P_{n+2}) = x\,\mu(P_{n+1}) - \mu(P_n).
\]
\end{definition}
The first instances are $\mu(P_2)=x^2-1$, $\mu(P_3)=x^3-2x$, $\mu(P_4)=x^4-3x^2+1$, $\mu(P_5)=x^5-4x^3+3x$; these equal $U_n(x/2)$ for the Chebyshev polynomial $U_n$ of the second kind.

\begin{lemma}[Monicity]
For every $n$, $\mu(P_n)$ is monic.
\end{lemma}
\begin{proof}[Proof sketch]
Two-step induction. Base cases are clear. An auxiliary induction gives $\deg\mu(P_n)=n$, so $\deg\mu(P_n) < \deg(x\,\mu(P_{n+1}))=n+2$ and the leading coefficient of the difference is that of $x\,\mu(P_{n+1})$, namely $1$.
\end{proof}

\begin{lemma}[Degree]
$\deg\mu(P_n)=n$ for all $n$; in particular $\mu(P_n)\ne 0$.
\end{lemma}
\begin{proof}[Proof sketch]
Strong induction. Monicity yields $\deg(x\,\mu(P_{n+1}))=n+2 > n = \deg\mu(P_n)$, so the top term survives the subtraction.
\end{proof}

\begin{lemma}[Value at $2$]
$\mu(P_n)(2) = n+1$.
\end{lemma}
\begin{proof}[Proof sketch]
Induction: $\mu(P_{n+2})(2) = 2(n+2)-(n+1) = n+3$.
\end{proof}

\section{Roots via the trigonometric substitution}

\begin{theorem}[Trigonometric evaluation]
For all $n\in\N$ and $\theta\in\R$,
\[
\mu(P_n)(2\cos\theta)\cdot\sin\theta = \sin\big((n+1)\theta\big).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Two-step induction. Base cases: $\sin\theta=\sin\theta$ and $2\cos\theta\sin\theta=\sin2\theta$. The step is the identity $\sin((n+2)\theta) = 2\cos\theta\sin((n+1)\theta) - \sin(n\theta)$, matching the recurrence.
\end{proof}

\begin{lemma}[Roots]
For $1\le k\le n$, $2\cos(k\pi/(n+1))$ is a root of $\mu(P_n)$.
\end{lemma}
\begin{proof}[Proof sketch]
Put $\theta=k\pi/(n+1)$: then $\sin((n+1)\theta)=\sin(k\pi)=0$ while $\sin\theta>0$ since $\theta\in(0,\pi)$; divide.
\end{proof}

\begin{theorem}[Complete root set and largest root]
For $n\ge1$ the real roots of $\mu(P_n)$ are exactly $\{2\cos(k\pi/(n+1)) : 1\le k\le n\}$, and the greatest, at $k=1$, is
\[
\mu(P_n) = 2\cos\!\Big(\frac{\pi}{n+1}\Big).
\]
\end{theorem}
\begin{proof}[Proof sketch]
The map $k\mapsto 2\cos(k\pi/(n+1))$ is injective on $\{1,\dots,n\}$ (invert with $\arccos$), giving $n$ distinct roots of a degree-$n$ polynomial, hence all of them. Strict monotonicity of cosine on $[0,\pi]$ makes $k=1$ the largest.
\end{proof}

\section{The sequence of largest matching roots}

Write $a_n := \mu(P_n) = 2\cos(\pi/(n+1))$, the largest matching root of $P_n$ (for $n\ge1$).

\begin{lemma}
$0\le a_n<2$ for all $n\ge1$.
\end{lemma}
\begin{lemma}
$(a_n)_{n\ge1}$ is strictly increasing.
\end{lemma}
\begin{lemma}
$a_n\to 2$ as $n\to\infty$.
\end{lemma}
\begin{proof}[Proof sketches]
Since $\pi/(n+1)\in(0,\pi/2]$ decreases strictly to $0$ and cosine is continuous and strictly decreasing on $[0,\pi]$ with $\cos0=1$, the values $2\cos(\pi/(n+1))$ are nonnegative, below $2$, strictly increasing, and converge to $2$.
\end{proof}

The staircase begins $a_2=1$, $a_3=\sqrt2$, $a_4=\tau$, $a_5=\sqrt3,\dots$ (with $a_1=0$).

\section{The golden-ratio threshold}

\begin{definition}
$\tau=\tfrac12(1+\sqrt5)$ and $T=\sqrt{2+\sqrt5}$.
\end{definition}

\begin{lemma}
$\tau + 1/\tau = \sqrt5$.
\end{lemma}
\begin{proof}[Proof sketch]
Equivalent to $\tau^2-\sqrt5\,\tau+1=0$, satisfied by $(1+\sqrt5)/2$.
\end{proof}

\begin{theorem}[Golden form]
$T = \sqrt\tau + 1/\sqrt\tau$.
\end{theorem}
\begin{proof}[Proof sketch]
Both sides nonnegative; compare squares: $(\sqrt\tau+1/\sqrt\tau)^2 = 2 + (\tau+1/\tau) = 2+\sqrt5 = T^2$.
\end{proof}

\begin{theorem}
$2 < T$.
\end{theorem}
\begin{proof}[Proof sketch]
$T^2 = 2+\sqrt5 > 4$ since $\sqrt5>2$; take positive roots. Numerically $T\approx 2.058$.
\end{proof}

\section{Capstone: accumulation below the golden fence}

\begin{theorem}[Main theorem]
The largest matching roots $a_n = \mu(P_n)$ satisfy: \emph{(1)} $a_n = 2\cos(\pi/(n+1))$ is the largest matching root of $P_n$; \emph{(2)} $(a_n)_{n\ge1}$ is strictly increasing; \emph{(3)} $a_n\in(-T,T)$; \emph{(4)} $a_n\to2$; \emph{(5)} $2<T$.
\end{theorem}
\begin{proof}[Proof sketch]
Items (1),(2),(4),(5) are the results above. For (3), $0\le a_n<2<T$ gives $-T<a_n<T$.
\end{proof}

\begin{theorem}[Accumulation point]
$2$ is an accumulation point of $\{a_n : n\ge1\}$.
\end{theorem}
\begin{proof}[Proof sketch]
Any neighborhood $U$ of $2$ contains all $a_n$ with $n$ large (convergence), and each such $a_n<2$ is distinct from $2$.
\end{proof}

Hence $2$ is a genuine accumulation point of largest matching roots strictly below the golden threshold $T$, realized by the explicit path family.

\begin{corollary}[Golden identity]
$\mu(P_4) = 2\cos(\pi/5) = \tfrac12(1+\sqrt5) = \tau$.
\end{corollary}
\begin{proof}[Proof sketch]
The largest root of $P_4$ is $2\cos(\pi/5)$ by the root theorem, and $\cos(\pi/5)=(1+\sqrt5)/4$; equivalently $\mu(P_4)=x^4-3x^2+1$ has largest root $\sqrt{(3+\sqrt5)/2}=\tau$.
\end{proof}

\section{Applications and future work}

For trees the matching polynomial is the adjacency characteristic polynomial, so these results describe spectral-radius limit points of paths within the Smith/Hoffman--Shearer threshold theory. The path matching polynomials are rescaled Chebyshev polynomials; in statistical mechanics the matching polynomial is the monomer--dimer partition function, and largest roots govern growth rates. Natural extensions: the cycles $C_n$ (also accumulating at $2$); the $D_n$/$E$-type families whose limit points fill the window $(2,T)$; a general matching-polynomial API with the edge-deletion recurrence $\mu(G)=\mu(G-e)-\mu(G-u-v)$; and a formal treatment of Heilmann--Lieb real-rootedness and interlacing. Completing this determines the full limit-point set $S$ below the golden threshold.

